{"actions":[{"type":"success_contract","objective":"Run Windows 3.11 for Workgroups in QEMU using /app/isos/win311.img, with VNC on :1 (port 5901), nginx on port 80 for web access, snapshot mode to keep the base image immutable, and programmatic keyboard input support so the VM can receive keystrokes beyond VNC interaction. Leave the VM running in the background at the Windows 3.11 desktop.","required_artifacts":["QEMU launch command or wrapper/config used to start the VM","nginx configuration or web interface setup on port 80","receipt-backed runtime evidence showing QEMU listening on VNC port 5901 and VM boot progress to Windows 3.11 desktop","receipt-backed evidence that QEMU was started in snapshot mode","receipt-backed evidence of a programmatic keyboard input path (e.g. QEMU monitor/serial/guest agent/control socket)"],"required_behaviors":["QEMU uses /app/isos/win311.img as the disk image","base disk remains immutable via snapshot mode","VNC display is :1 and reachable on port 5901","nginx listens on port 80 for remote access","VM remains running in the background after startup","QEMU accepts keyboard input programmatically, not only through VNC"],"known_invalid_patterns":["File existence without runtime evidence","Compilation or syntax checks without VM behavior","Non-empty output or prompt echo without proving the VM is at the Windows desktop","VNC-only interaction without a separate programmatic keyboard control path","Starting QEMU without snapshot mode"],"verification_plan":["Inspect available files and prior receipts for existing VM launch scripts or configs","If needed, create a launch script and nginx config","Start QEMU in the background with snapshot mode, VNC :1, and a control interface for programmatic keyboard input","Start or configure nginx on port 80","Verify via receipts that QEMU is listening on 5901 and that the VM reaches the Windows 3.11 desktop","Verify the keyboard control path by sending a programmatic keystroke through the configured interface"],"finalization_evidence_required":["Receipt showing the exact QEMU invocation with snapshot mode, VNC :1, and a programmatic control interface","Receipt showing QEMU listening on port 5901 and nginx listening on port 80","Receipt showing the VM booted to the Windows 3.11 desktop","Receipt showing a programmatic keystroke was delivered successfully"]},{"type":"plan_update","plan":{"status":"next","steps":["Inspect workspace and prior receipts for existing VM/QEMU/nginx setup","Create or reuse a launch script/config if absent","Start QEMU in background with snapshot mode, VNC :1, and a control interface for keyboard input","Configure nginx on port 80","Verify runtime state and collect receipts"]}},{"type":"working_checklist","items":["Find existing VM launch artifacts or receipts","Ensure QEMU command includes snapshot mode and VNC :1","Ensure a programmatic keyboard control path exists","Ensure nginx serves on port 80","Collect runtime receipts for ports and desktop state"]}]}
